<?php declare(strict_types=1);require __DIR__.'/config/bootstrap.php';$products=[];try{$products=db()->query('SELECT p.id,p.name,p.price,p.currency,p.image_url,g.name game FROM products p JOIN games g ON g.id=p.game_id WHERE p.active=1 AND g.active=1 ORDER BY g.name,p.price')->fetchAll();}catch(Throwable $e){} ?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars(config('app.name','SOMBA'))?> — Gaming Top-Up</title><link rel="stylesheet" href="assets/style.css"></head><body><header><strong>SOMBA</strong><nav><a href="#packs">Packs</a><a href="admin/">Admin</a></nav></header><section class="hero"><small>GAMING TOP-UP</small><h1>Recharge tes jeux.<br><span>Simplement.</span></h1><p>Choisis ton jeu et ton pack, renseigne tes informations, puis paie via Maketou.</p><a class="btn" href="#packs">Voir les packs</a></section><section id="packs"><h2>Nos packs</h2><div class="grid"><?php foreach($products as $p):?><article><div class="cover"><?php if($p['image_url']):?><img src="<?=htmlspecialchars($p['image_url'])?>" alt=""><?php else:?><span>🎮</span><?php endif;?></div><h3><?=htmlspecialchars($p['game'])?></h3><p><?=htmlspecialchars($p['name'])?></p><strong><?=htmlspecialchars(number_format((float)$p['price'],0,',',' ').' '.$p['currency'])?></strong><button class="btn" onclick="buy(<?=$p['id']?>)">Acheter</button></article><?php endforeach;if(!$products):?><p>Aucun pack disponible pour le moment.</p><?php endif;?></div></section><footer>SOMBA © <?=date('Y')?></footer><script>async function buy(id){const email=prompt('Email :');if(!email)return;const firstName=prompt('Prénom :');if(!firstName)return;const lastName=prompt('Nom :');if(!lastName)return;const phone=prompt('Téléphone (facultatif) :')||'';const identifier=prompt('Identifiant joueur / données nécessaires au top-up :');if(!identifier)return;const r=await fetch('api/checkout.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:id,email,firstName,lastName,phone,customer:{identifier}})});const j=await r.json();if(j.redirectUrl)location.href=j.redirectUrl;else alert(j.error||'Impossible de créer le paiement.');}</script></body></html>